<div class="vx-workspace-grid"><div class="vx-panel vx-panel-console"><div class="vx-panel-head"><div><span class="vx-eyebrow">LIVE TERMINAL</span><h3>Server console</h3></div><a href="serverlogdownload.php?id=<?= $sid ?>">Download log ↧</a></div><pre id="swConsoleOut" class="vx-console">Connecting to console…</pre><?php if($live): ?><div class="vx-console-row"><input id="swConsoleCmd" placeholder="Send a command…" autocomplete="off"><button type="button" class="vx-btn vx-btn-bright" onclick="swConsoleSend()">Send ↵</button></div><div class="vx-quickcmds"><button onclick="swConsoleQuick('status')">status</button><button onclick="swConsoleQuick('stats')">stats</button><button onclick="swConsoleQuick('users')">users</button></div><?php endif; ?></div><div class="vx-panel"><div class="vx-panel-head"><div><span class="vx-eyebrow">TELEMETRY</span><h3>Server snapshot</h3></div><a href="" onclick="location.reload();return false">Refresh</a></div><dl class="vx-details"><dt>State</dt><dd><span class="vx-status <?= $live?'live':'idle' ?>"><i></i><?= htmlspecialchars($online) ?></span></dd><dt>Game</dt><dd><?= htmlspecialchars($srv['game']??'—') ?></dd><dt>Slots</dt><dd><?= (int)($srv['slots']??0) ?></dd><dt>Node</dt><dd><?= htmlspecialchars($srv['boxlocation']??'—') ?></dd><?php if(!empty($query)&&is_array($query)): foreach($query as $k=>$v): ?><dt><?= htmlspecialchars((string)$k) ?></dt><dd><?= htmlspecialchars((string)$v) ?></dd><?php endforeach; endif; ?></dl></div></div>
<?php if ($live): ?><script>(function(){var sid=<?= $sid ?>,out=document.getElementById('swConsoleOut'),input=document.getElementById('swConsoleCmd'),busy=false;function send(c){if(busy)return;busy=true;var x=new XMLHttpRequest();x.open('POST','serverconsole.php',true);x.setRequestHeader('Content-Type','application/x-www-form-urlencoded');x.onload=function(){busy=false;try{var r=JSON.parse(x.responseText);out.textContent=r.ok?r.output:(r.error||'Console unavailable');out.scrollTop=out.scrollHeight;}catch(e){out.textContent='Console returned an invalid response.';}};x.send('id='+sid+'&command='+encodeURIComponent(c||''));}window.swConsoleSend=function(){var c=input.value;input.value='';send(c);return false};window.swConsoleQuick=function(c){input.value=c;swConsoleSend()};send('');})();</script><?php endif; ?>
